import{_ as l,o as t,c as r,aw as e}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Рефакторинг","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/refactoring/best-practices/refactoring.md","filePath":"wiki/dev-commit/theory/refactoring/best-practices/refactoring.md"}'),a={name:"wiki/dev-commit/theory/refactoring/best-practices/refactoring.md"};function o(n,i,s,c,g,h){return t(),r("div",null,[...i[0]||(i[0]=[e('<h1 id="рефакторинг" tabindex="-1">Рефакторинг <a class="header-anchor" href="#рефакторинг" aria-label="Permalink to &quot;Рефакторинг&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Рефакторинг (refactoring)</strong> - процесс изменения внутренней структуры программы, не затрагивающий её внешнего поведения и имеющий целью облегчить понимание её работы. В основе рефакторинга лежит последовательность небольших эквивалентных (то есть сохраняющих поведение) преобразований. Поскольку каждое преобразование маленькое, программисту легче проследить за его правильностью, и в то же время вся последовательность может привести к существенной перестройке программы и улучшению её согласованности и чёткости</li><li>Цель рефакторинга — сделать код программы более легким для понимания; без этого рефакторинг нельзя считать успешным</li><li>Рефакторинг следует отличать от оптимизации производительности. Как и рефакторинг, оптимизация обычно не изменяет поведение программы, а только ускоряет её работу. Но оптимизация часто затрудняет понимание кода, что противоположно рефакторингу</li><li>С другой стороны, нужно отличать рефакторинг от реинжиниринга, который осуществляется для расширения функциональности программного обеспечения. Как правило, крупные рефакторинги предваряют реинжиниринг</li></ul></div><h2 id="причины-применения-рефакторинга" tabindex="-1">Причины применения рефакторинга <a class="header-anchor" href="#причины-применения-рефакторинга" aria-label="Permalink to &quot;Причины применения рефакторинга&quot;">​</a></h2><ol><li>Необходимо добавить новую функцию, которая недостаточно укладывается в принятое архитектурное решение</li><li>Необходимо исправить ошибку, причины возникновения которой сразу не ясны</li><li>Преодоление трудностей в командной разработке, которые обусловлены сложной логикой программы</li></ol><h2 id="признаки-плохого-кода" tabindex="-1">Признаки плохого кода <a class="header-anchor" href="#признаки-плохого-кода" aria-label="Permalink to &quot;Признаки плохого кода&quot;">​</a></h2><ol><li>Дублирование кода</li><li>Длинный метод</li><li>Большой класс</li><li>Длинный список параметров</li><li>&quot;Жадные&quot; функции - это метод, который чрезмерно обращается к данным другого объекта</li><li>Избыточные временные переменные</li><li>Классы данных</li><li>Несгруппированные данные</li></ol><h2 id="методы-рефакторинга" tabindex="-1">Методы рефакторинга <a class="header-anchor" href="#методы-рефакторинга" aria-label="Permalink to &quot;Методы рефакторинга&quot;">​</a></h2><ul><li><strong>Изменение сигнатуры метода (change method signature)</strong> - добавление, изменение или удаление параметра метода. Изменив сигнатуру метода, необходимо скорректировать обращения к нему в коде всех клиентов. Это изменение может затронуть внешний интерфейс программы, кроме того, не всегда разработчику, изменяющему интерфейс, доступны все клиенты этого интерфейса, поэтому может потребоваться та или иная форма регистрации изменений интерфейса для последующей передачи их вместе с новой версией программы</li><li><strong>Инкапсуляция поля (encapsulate field)</strong> - в случае, если у класса имеется открытое поле, необходимо сделать его закрытым и обеспечить методы доступа. После «Инкапсуляции поля» часто применяется «Перемещение метода»</li><li><strong>Выделение класса (extract class)</strong></li><li><strong>Выделение интерфейса (extract interface)</strong></li><li><strong>Выделение локальной переменной (extract local variable)</strong></li><li><strong>Выделение метода (extract method)</strong> - выделение из длинного и/или требующего комментариев кода отдельных фрагментов и преобразовании их в отдельные методы, с подстановкой подходящих вызовов в местах использования. В этом случае действует правило: если фрагмент кода требует комментария о том, что он делает, то он должен быть выделен в отдельный метод. Также правило: один метод не должен занимать более чем один экран (25-50 строк, в зависимости от условий редактирования), в противном случае некоторые его фрагменты имеют самостоятельную ценность и подлежат выделению. Из анализа связей выделяемого фрагмента с окружающим контекстом делается вывод о перечне параметров нового метода и его локальных переменных</li><li><strong>Генерализация типа (generalize type)</strong></li><li><strong>Встраивание (inline)</strong></li><li><strong>Введение фабрики (introduce factory)</strong></li><li><strong>Введение параметра (introduce parameter)</strong></li><li><strong>Подъём метода (pull up method)</strong></li><li><strong>Спуск метода (push down method)</strong></li><li><strong>Переименование метода (rename method)</strong></li><li><strong>Перемещение метода (move method)</strong> - применяется по отношению к методу, который чаще обращается к другому классу, чем к тому, в котором сам располагается</li><li><strong>Замена условного оператора полиморфизмом (replace conditional with polymorphism)</strong> - условный оператор с несколькими ветвями заменяется вызовом полиморфного метода некоторого базового класса, имеющего подклассы для каждой ветви исходного оператора. Выбор ветви осуществляется неявно, в зависимости от того, экземпляру какого из подклассов оказался адресован вызов</li><li><strong>Замена наследования делегированием (replace inheritance with delegation)</strong></li><li><strong>Замена кода типа подклассами (replace type code with subclasses)</strong></li></ul><h2 id="проблемы-возникающие-при-проведении-рефакторинга" tabindex="-1">Проблемы, возникающие при проведении рефакторинга <a class="header-anchor" href="#проблемы-возникающие-при-проведении-рефакторинга" aria-label="Permalink to &quot;Проблемы, возникающие при проведении рефакторинга&quot;">​</a></h2><ul><li>Проблемы, связанные с базами данных</li><li>Проблемы изменения интерфейсов</li><li>Трудности при изменении дизайна</li></ul><h2 id="средства-автоматизации-рефакторинга" tabindex="-1">Средства автоматизации рефакторинга <a class="header-anchor" href="#средства-автоматизации-рефакторинга" aria-label="Permalink to &quot;Средства автоматизации рефакторинга&quot;">​</a></h2><p><strong>Технические критерии для инструментов рефакторинга:</strong></p><ul><li>Базы данных программы</li><li>Деревья синтаксического разбора</li><li>Точность</li></ul><p><strong>Практические критерии для инструментов рефакторинга:</strong></p><ul><li>Скорость</li><li>Отмена модификаций</li><li>Интеграция с другими инструментами</li></ul>',16)])])}const m=l(a,[["render",o]]);export{u as __pageData,m as default};
